// Test script for observeApiError
import { observeApiError, MetricsApiStatusTypes } from './packages/metrics/lib/observeApiError';

const results: string[] = [];
const metricObserver = (status: MetricsApiStatusTypes) => results.push(status);

// Test falsy values
observeApiError(undefined, metricObserver);
console.assert(results[results.length - 1] === 'failure', `Expected 'failure', got '${results[results.length - 1]}'`);

observeApiError(null, metricObserver);
console.assert(results[results.length - 1] === 'failure', `Expected 'failure', got '${results[results.length - 1]}'`);

observeApiError('', metricObserver);
console.assert(results[results.length - 1] === 'failure', `Expected 'failure', got '${results[results.length - 1]}'`);

observeApiError(0, metricObserver);
console.assert(results[results.length - 1] === 'failure', `Expected 'failure', got '${results[results.length - 1]}'`);

observeApiError(false, metricObserver);
console.assert(results[results.length - 1] === 'failure', `Expected 'failure', got '${results[results.length - 1]}'`);

// Test 4xx status
observeApiError({ status: 400 }, metricObserver);
console.assert(results[results.length - 1] === '4xx', `Expected '4xx', got '${results[results.length - 1]}'`);

observeApiError({ status: 404 }, metricObserver);
console.assert(results[results.length - 1] === '4xx', `Expected '4xx', got '${results[results.length - 1]}'`);

observeApiError({ status: 499 }, metricObserver);
console.assert(results[results.length - 1] === '4xx', `Expected '4xx', got '${results[results.length - 1]}'`);

// Test 5xx status
observeApiError({ status: 500 }, metricObserver);
console.assert(results[results.length - 1] === '5xx', `Expected '5xx', got '${results[results.length - 1]}'`);

observeApiError({ status: 503 }, metricObserver);
console.assert(results[results.length - 1] === '5xx', `Expected '5xx', got '${results[results.length - 1]}'`);

observeApiError({ status: 599 }, metricObserver);
console.assert(results[results.length - 1] === '5xx', `Expected '5xx', got '${results[results.length - 1]}'`);

// Test status < 400
observeApiError({ status: 200 }, metricObserver);
console.assert(results[results.length - 1] === 'failure', `Expected 'failure', got '${results[results.length - 1]}'`);

observeApiError({ status: 0 }, metricObserver);
console.assert(results[results.length - 1] === 'failure', `Expected 'failure', got '${results[results.length - 1]}'`);

// Test that metricObserver is called exactly once
let callCount = 0;
const resetObserver = () => { results.length = 0; callCount = 0; };
const countingObserver: MetricsApiStatusTypes = '' as any;
const wrappedObserver = (status: MetricsApiStatusTypes) => { callCount++; };
observeApiError({ status: 404 }, wrappedObserver);
console.assert(callCount === 1, `Expected exactly 1 call, got ${callCount}`);

console.log('All tests passed!');

